const body = $input.first().json.body || $input.first().json;
const eventType = body.event_type || body.event || (body.fromMe ? 'outgoing_message_phone' : 'incoming_message');
const whatsappId = body.chatId || body.remoteJid || body.from || body.key?.remoteJid || '';
const isGroup = whatsappId.endsWith('@g.us') || Boolean(body.isGroup);

let contentType = (body.type || body.messageType || 'text').toLowerCase();
if (contentType === 'voice') contentType = 'ptt';

const textContent = body.text || body.body || body.caption || body.message?.conversation || '';
const mediaUrl = body.mediaUrl || body.media?.url || body.imageUrl || body.audioUrl || body.videoUrl || '';

return [{
  json: {
    received_at_ms: Date.now(),
    event_type: eventType,
    whatsapp_id: whatsappId,
    phone_number: whatsappId.replace(/@.*$/, ''),
    display_name: body.senderName || body.pushName || 'Клиент',
    is_group: isGroup,
    content_type: contentType,
    text_content: textContent,
    media_url: mediaUrl,
    external_message_id: body.id || body.key?.id || `msg_${Date.now()}`,
    raw_payload: body
  }
}];

