const base = $('Is Manager Outgoing Message?').first().json;
const item = $input.first().json;

let unifiedText = base.text_content || '';
let mediaAttached = Boolean(base.media_url);

if (base.content_type === 'image') {
  const visionDescription = item.choices?.[0]?.message?.content || 'Фото получено (описание недоступно)';
  unifiedText = `[ФОТО ОТ КЛИЕНТА: ${base.media_url}] Подпись клиента: "${base.text_content || 'без подписи'}". Визуальный анализ ИИ: ${visionDescription}`;
  mediaAttached = true;
} else if (base.content_type === 'video') {
  unifiedText = `[ВИДЕО ОТ КЛИЕНТА: ${base.media_url}] Подпись клиента: "${base.text_content || 'клиент прислал видео проблемы'}"` ;
  mediaAttached = true;
} else if (base.content_type === 'audio' || base.content_type === 'ptt') {
  const transcript = item.text || '';
  unifiedText = `[ГОЛОСОВОЕ СООБЩЕНИЕ (расшифровка Whisper)]: ${transcript}`;
}

return [{
  json: {
    ...base,
    normalized_user_input: unifiedText.trim() || '[Пустое сообщение]',
    media_attached_now: mediaAttached
  }
}];

