parameters.jsCode:
const rawAgent = $input.first().json.output || $input.first().json;
const contact = $('Upsert & Load Contact State').first().json;
const incoming = $('Unify Multimodal Input').first().json;

const ALLOWED_STAGES = new Set([
  'NEW_CONTACT', 'INTENT_CLASSIFICATION', 'LEASING_QUALIFICATION',
  'LEASING_PRESENTATION', 'VIEWING_HANDOFF', 'MAINTENANCE_TRIAGE',
  'URGENCY_CHECK', 'EMERGENCY_ESCALATION', 'TICKET_CREATED',
  'STATUS_INQUIRY', 'HUMAN_HANDOFF', 'FOLLOWUP_WAITING', 'RESOLVED_CLOSED'
]);

const ALLOWED_ACTIONS = new Set([
  'none', 'update_data', 'create_ticket', 'escalate_urgent',
  'transfer_to_manager', 'book_viewing', 'mark_closed'
]);

const ALLOWED_URGENCY = new Set(['low', 'medium', 'high', 'emergency']);
const ALLOWED_ROLES = new Set(['tenant', 'prospect', 'unknown']);
const ALLOWED_CATEGORIES = new Set(['plumbing', 'heating', 'electrical', 'appliance', 'general', 'leasing']);

const previousStage = contact.current_stage || 'NEW_CONTACT';
const validatedStage = ALLOWED_STAGES.has(rawAgent.new_stage) ? rawAgent.new_stage : previousStage;
let validatedAction = ALLOWED_ACTIONS.has(rawAgent.action) ? rawAgent.action : 'none';
const validatedUrgency = ALLOWED_URGENCY.has(rawAgent.urgency) ? rawAgent.urgency : 'low';
const validatedRole = ALLOWED_ROLES.has(rawAgent.role) ? rawAgent.role : (contact.role || 'unknown');

if (validatedUrgency === 'emergency' && validatedAction !== 'escalate_urgent') {
  validatedAction = 'escalate_urgent';
}

const prevData = contact.collected_data || {};
const newData = rawAgent.collected_data || {};

const mergedCollectedData = {
  building_address: (newData.building_address || prevData.building_address || '').trim(),
  unit_number: (newData.unit_number || prevData.unit_number || '').trim(),
  issue_category: ALLOWED_CATEGORIES.has(newData.issue_category)
    ? newData.issue_category
    : (prevData.issue_category || 'general'),
  issue_description: (newData.issue_description || prevData.issue_description || '').trim(),
  media_attached: Boolean(newData.media_attached || prevData.media_attached || incoming.media_attached_now),
  preferred_viewing_time: (newData.preferred_viewing_time || prevData.preferred_viewing_time || '').trim(),
  budget_or_beds: (newData.budget_or_beds || prevData.budget_or_beds || '').trim()
};

const cleanReply = String(rawAgent.reply || 'Спасибо за обращение! Мы уже обрабатываем ваш запрос.')
  .replace(/[*_`#]+/g, '')
  .trim();

const responseTimeMs = Math.max(0, Date.now() - (incoming.received_at_ms || Date.now()));

// Генерация бизнес-событий для аналитики
const events = [];
if (validatedStage !== previousStage) {
  events.push({
    event_type: 'stage_entered',
    from_stage: previousStage,
    to_stage: validatedStage,
    action_taken: validatedAction,
    urgency: validatedUrgency
  });
}
if (validatedAction === 'create_ticket') {
  events.push({
    event_type: 'ticket_created',
    from_stage: previousStage,
    to_stage: validatedStage,
    action_taken: validatedAction,
    urgency: validatedUrgency
  });
}
if (validatedAction === 'escalate_urgent' || validatedUrgency === 'emergency') {
  events.push({
    event_type: 'emergency_escalated',
    from_stage: previousStage,
    to_stage: validatedStage,
    action_taken: 'escalate_urgent',
    urgency: 'emergency'
  });
}
if (validatedAction === 'book_viewing') {
  events.push({
    event_type: 'viewing_requested',
    from_stage: previousStage,
    to_stage: validatedStage,
    action_taken: validatedAction,
    urgency: validatedUrgency
  });
}
if (validatedAction === 'transfer_to_manager') {
  events.push({
    event_type: 'transferred_to_manager',
    from_stage: previousStage,
    to_stage: validatedStage,
    action_taken: validatedAction,
    urgency: validatedUrgency
  });
}

// Маршрутный ключ для Switch
let routeBranch = 'STANDARD_REPLY';
if (validatedUrgency === 'emergency' || validatedAction === 'escalate_urgent') {
  routeBranch = 'EMERGENCY';
} else if (validatedAction === 'create_ticket') {
  routeBranch = 'CREATE_TICKET';
} else if (validatedAction === 'book_viewing' || validatedAction === 'transfer_to_manager') {
  routeBranch = 'BOOK_VIEWING_OR_HANDOFF';
}

const headerEmoji = routeBranch === 'EMERGENCY'
  ? '🚨 АВАРИЙНЫЙ ВЫЗОВ (EMERGENCY)'
  : (validatedAction === 'book_viewing' ? '🏠 ЗАПИСЬ НА ПРОСМОТР (LEASING)' : '📋 ПЕРЕДАЧА ДИАЛОГА МЕНЕДЖЕРУ');

const managerCard = [
  headerEmoji,
  `Клиент: ${contact.display_name} (${contact.phone_number})`,
  `Роль: ${validatedRole} | Этап: ${validatedStage}`,
  `Срочность: ${validatedUrgency.toUpperCase()}`,
  mergedCollectedData.building_address ? `Объект/Адрес: ${mergedCollectedData.building_address}` : null,
  mergedCollectedData.unit_number ? `Квартира: ${mergedCollectedData.unit_number}` : null,
  mergedCollectedData.issue_category ? `Категория: ${mergedCollectedData.issue_category}` : null,
  mergedCollectedData.issue_description ? `Описание: ${mergedCollectedData.issue_description}` : null,
  mergedCollectedData.budget_or_beds ? `Параметры поиска: ${mergedCollectedData.budget_or_beds}` : null,
  mergedCollectedData.preferred_viewing_time ? `Желаемое время просмотра: ${mergedCollectedData.preferred_viewing_time}` : null,
  incoming.media_url ? `Медиафайл: ${incoming.media_url}` : null,
  `Заметка ИИ: ${rawAgent.internal_note || 'нет'}`,
  `Confidence: ${rawAgent.confidence ?? 0.9}`
].filter(Boolean).join('\n');

return [{
  json: {
    whatsapp_id: contact.whatsapp_id,
    phone_number: contact.phone_number,
    display_name: contact.display_name,
    reply: cleanReply,
    role: validatedRole,
    previous_stage: previousStage,
    new_stage: validatedStage,
    action: validatedAction,
    urgency: validatedUrgency,
    collected_data: mergedCollectedData,
    handoff_type: rawAgent.handoff_type || 'general_support',
    internal_note: rawAgent.internal_note || '',
    confidence: Number(rawAgent.confidence ?? 0.9),
    response_time_ms: responseTimeMs,
    media_url: incoming.media_url || '',
    events,
    route_branch: routeBranch,
    manager_card: managerCard
  }
}];

const validated = $('Validate & Normalize Output (Code)').first().json;
let finalReply = validated.reply;
let createdTicketNumber = null;

if (validated.route_branch === 'EMERGENCY') {
  createdTicketNumber = $('Branch 1: Create URGENT Ticket & Pause Bot').first()?.json?.ticket_number || null;
} else if (validated.route_branch === 'CREATE_TICKET') {
  createdTicketNumber = $('Branch 2: Create Routine Ticket in DB').first()?.json?.ticket_number || null;
}

if (createdTicketNumber) {
  if (finalReply.includes('{{TICKET_NUMBER}}')) {
    finalReply = finalReply.replace(/\{\{TICKET_NUMBER\}\}/g, createdTicketNumber);
  } else {
    finalReply = `${finalReply}\n\nНомер вашей заявки: ${createdTicketNumber}`;
  }
}

return [{
  json: {
    ...validated,
    ticket_number: createdTicketNumber,
    final_reply_text: finalReply
  }
}];

